  "brain.py": "\"\"\"Retry brain - resilience patterns on plain dispatch: retry, STOP, rollback.\n\n    python brain.py all\n\n    index-node      VectorEngram with a per-trace inverse-op journal\n    ingester-node   imprints chunks; can crash partway on request\n    generator-node  a fake LLM that stalls on request\n    terminal-node   runs the scenarios\n\n1. run_with_retry  a stalled stage is retried on a fresh trace; the\n                   abandoned attempt is STOPped so it cannot keep running.\n2. stop_trace      cooperative cancellation of a whole workflow.\n3. rollback=True   replays the Engram's journal for that trace, so a\n                   half-finished ingest leaves no partial chunks behind.\n\"\"\"\nimport asyncio\nimport contextlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, SYNAPSE_URL\nfrom index import VECTORS\nfrom neurons import generator, ingester\nfrom receptors import terminal\n\n\ndef build_index(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"index-node\", role=\"worker\")\n    node.attach_engram(VECTORS)\n    return node\n\n\ndef build_neuron(synapse, axon) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=f\"{axon.neuron_id}-node\", role=\"worker\")\n    node.attach_axon(axon)\n    return node\n\n\ndef build_terminal(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"terminal-node\", heartbeat_s=0)\n    node.attach_receptor(terminal.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            build_index(synapse),\n            build_neuron(synapse, ingester.AXON),\n            build_neuron(synapse, generator.AXON),\n            build_terminal(synapse),\n        )\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
